 p('Parent is phi(n), oriented toward 1; layer is distance from centre 1024, not orbit depth. At n = 1 the parent entry 1 denotes a suppressed loop. Products use prime bases and integer exponents.','Small2')
 data=[['Label n','Prime factorization','Parent phi(n)','Layer']]
 for x in sub:
  f=' * '.join(str(q)+(('^'+str(e)) if e>1 else '') for q,e in x['factorization']) or '1'
  data.append([str(x['label']),f,str(x['phi']),str(x['layer'])]);md.append(' | '.join(data[-1]))
