 tab.setStyle(TableStyle([('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTNAME',(0,1),(-1,-1),'Courier'),('FONTSIZE',(0,0),(-1,-1),8.1),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e5edf3')),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#34546b')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f6f8fa')]),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),1),('BOTTOMPADDING',(0,0),(-1,-1),1)]));story.append(tab)
 if part==1:p('The table is sorted by label. Rows on the following page complete the same orbit set; no edges other than the listed non-loop parent edges are present.','Small2')
 else:p('Proof, continued. There are 88 vertices and 87 edges. The independent checker constructs the recursive D_4 separately, matches rooted canonical tree strings, and emits a bijection preserving all edges. It also compares every ordered pair against the actual Lean preorder labels. The three rooted components at 1024 each have the arm(3) shape, including all nonedges. This proves the required isomorphism; matching the layer profile alone would not suffice. The largest label is 11732914. A single stage-4 realization negates the universal conjecture. QED.','Small2')
